// ------------------------------------------------------------
// PROFILE PARSING
// ------------------------------------------------------------

function extractProfiles(row) {
  const value = row?.profile_array;

  if (Array.isArray(value)) {
    return value;
  }

  if (value && typeof value === 'object') {
    return [value];
  }

  if (typeof value === 'string') {
    try {
      const parsed = JSON.parse(value);

      if (Array.isArray(parsed)) {
        return parsed;
      }

      if (parsed && typeof parsed === 'object') {
        return [parsed];
      }
    } catch {
      return [];
    }
  }

  return [];
}


// ------------------------------------------------------------
// FETCH ALL PROFILES
// ------------------------------------------------------------

async function fetchProfiles() {
  const endpoint =
    `${SUPABASE_URL}/rest/v1/user_data?select=id,profile_array`;

  const response = await fetch(endpoint, {
    headers: {
      apikey: SUPABASE_KEY,
      Authorization: `Bearer ${SUPABASE_KEY}`
    }
  });

  if (!response.ok) {
    throw new Error('Registry unavailable');
  }

  const rows = await response.json();

  const profiles = [];
  let processedProfiles = 0;

  // Yield while processing both rows and large profile arrays.
  for (let rowIndex = 0; rowIndex < rows.length; rowIndex++) {
    const row = rows[rowIndex];
    const rowProfiles = extractProfiles(row);

    for (const profile of rowProfiles) {
      if (profile && profile.tfcNumber) {
        profiles.push({
          ...profile,
          _rowId: row.id
        });
      }

      processedProfiles++;
      if (processedProfiles % 25 === 0) {
        await new Promise((resolve) => setTimeout(resolve, 0));
      }
    }

    if (rowIndex % 25 === 0) {
      await new Promise((resolve) => setTimeout(resolve, 0));
    }
  }

  return profiles;
}


// ------------------------------------------------------------
// FIND PROFILE
// ------------------------------------------------------------

async function fetchProfile(tfcNumber) {

  const profiles =
    await fetchProfiles();

  // Keep the global profile list
  // synchronized with the registry.
  allProfiles = profiles;

  return (
    profiles.find(
      (profile) =>
        String(profile.tfcNumber) ===
        String(tfcNumber)
    ) || null
  );
}


// ------------------------------------------------------------
// ESCAPE HTML
// ------------------------------------------------------------

function escapeHtml(value) {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}


// ------------------------------------------------------------
// RENDER PROFILE TABLE
// ------------------------------------------------------------

async function renderProfiles(profiles) {
  const tbody =
    document.querySelector('.profile-table tbody');

  if (!tbody) {
    console.error('Profile table body not found.');
    return;
  }

  tbody.innerHTML = '';

  for (let profileIndex = 0; profileIndex < profiles.length; profileIndex++) {
    const profile = profiles[profileIndex];
    const tfcNumber =
      String(profile.tfcNumber || '');

    const isAdmin =
      tfcNumber === ADMIN_TFC_NUMBER;

    const isDisabled =
      tfcNumber.startsWith('A');

    const displayName =
      escapeHtml(
        profile.name || 'Unnamed operator'
      );

    const row =
      document.createElement('tr');

    row.innerHTML = `
      <td class="${isDisabled ? 'disabled-name' : ''}">
        ${displayName}
      </td>

      <td>
        ${escapeHtml(
          (profile.classes || []).join(' / ') ||
          'No class assignment'
        )}
      </td>

      <td>
        ${escapeHtml(
          profile.savedAt || '—'
        )}
      </td>

      <td>
        ${escapeHtml(
          (profile.mountains || []).join(', ') ||
          'Unassigned'
        )}
      </td>

      <td class="${isDisabled ? 'disabled-tfc' : ''}">
        ${escapeHtml(tfcNumber)}
      </td>

      <td>
        ${escapeHtml(
          profile.akotahiNumber || '—'
        )}
      </td>

      <td>
        ${escapeHtml(
          profile.pastoralNotes || 'None recorded'
        )}
      </td>

      <td class="profile-action">
        ${
          isAdmin
            ? `
              <span class="admin-label">
                MAIN ACCOUNT
              </span>
            `
            : `
              <button
                class="account-button ${isDisabled ? 'enable-button' : 'disable-button'}"
                type="button"
                data-tfc="${escapeHtml(tfcNumber)}"
              >
                ${isDisabled
                  ? 'ENABLE ACCOUNT'
                  : 'DISABLE ACCOUNT'}
              </button>
            `
        }
      </td>
    `;

    tbody.appendChild(row);

    // Yield during large renders so the preview watchdog does not
    // mistake table construction for an infinite loop.
    if (profileIndex > 0 && profileIndex % 25 === 0) {
      await new Promise((resolve) => setTimeout(resolve, 0));
    }
  }


  // ----------------------------------------------------------
  // UPDATE ROW COUNT
  // ----------------------------------------------------------

  const rowCount =
    tbody.querySelectorAll('tr').length;

  $('.editor-status').innerHTML =
    `<span>● ${rowCount} ${rowCount === 1 ? 'row' : 'rows'} loaded</span>` +
    '<span>Registry handshake complete</span>' +
    '<span>Profiles decrypted in memory</span>';


  // ----------------------------------------------------------
  // ACCOUNT BUTTON HANDLERS
  // ----------------------------------------------------------

  tbody
    .querySelectorAll('.account-button')
    .forEach((button) => {

      button.addEventListener(
        'click',
        () => {
          const tfc =
            button.dataset.tfc;

          const disabled =
            String(tfc).startsWith('A');

          if (disabled) {
            enableAccount(tfc);
          } else {
            disableAccount(tfc);
          }
        }
      );

    });
}



// ------------------------------------------------------------
// UPDATE ACCOUNT NUMBER IN SUPABASE
// ------------------------------------------------------------

async function updateAccountNumber(
  currentTfcNumber,
  newTfcNumber
) {
  const profile =
    allProfiles.find(
      (item) =>
        String(item.tfcNumber) ===
        String(currentTfcNumber)
    );

  if (!profile) {
    throw new Error(
      'Profile could not be found.'
    );
  }

  const rowId =
    profile._rowId;

  if (!rowId) {
    throw new Error(
      'Database row could not be identified.'
    );
  }


  // Fetch latest database version.
  const getEndpoint =
    `${SUPABASE_URL}/rest/v1/user_data?id=eq.${encodeURIComponent(rowId)}&select=id,profile_array`;

  const getResponse =
    await fetch(getEndpoint, {
      headers: {
        apikey: SUPABASE_KEY,
        Authorization:
          `Bearer ${SUPABASE_KEY}`
      }
    });

  if (!getResponse.ok) {
    throw new Error(
      'Unable to read the profile from the registry.'
    );
  }

  const rows =
    await getResponse.json();

  if (!rows.length) {
    throw new Error(
      'The database profile no longer exists.'
    );
  }

  const row =
    rows[0];

  let profileArray =
    row.profile_array;


  // Parse JSON if stored as text.
  if (typeof profileArray === 'string') {
    try {
      profileArray =
        JSON.parse(profileArray);
    } catch {
      throw new Error(
        'The profile_array contains invalid JSON.'
      );
    }
  }


  // Convert a single object into an array.
  if (!Array.isArray(profileArray)) {
    profileArray =
      [profileArray];
  }


  let found = false;

  profileArray =
    profileArray.map((item) => {

      if (
        item &&
        String(item.tfcNumber) ===
          String(currentTfcNumber)
      ) {

        found = true;

        return {
          ...item,
          tfcNumber: newTfcNumber
        };
      }

      return item;
    });


  if (!found) {
    throw new Error(
      'Matching profile was not found in the database.'
    );
  }


  // ----------------------------------------------------------
  // PATCH SUPABASE
  // ----------------------------------------------------------

  const updateEndpoint =
    `${SUPABASE_URL}/rest/v1/user_data?id=eq.${encodeURIComponent(rowId)}`;

  const updateResponse =
    await fetch(updateEndpoint, {
      method: 'PATCH',

      headers: {
        apikey: SUPABASE_KEY,
        Authorization:
          `Bearer ${SUPABASE_KEY}`,
        'Content-Type':
          'application/json',
        Prefer:
          'return=representation'
      },

      body: JSON.stringify({
        profile_array:
          profileArray
      })
    });


  if (!updateResponse.ok) {
    const errorText =
      await updateResponse.text();

    console.error(
      'Supabase update error:',
      errorText
    );

    throw new Error(
      'Unable to update the registry.'
    );
  }
}


// ------------------------------------------------------------
// DISABLE ACCOUNT
// ------------------------------------------------------------

async function disableAccount(
  tfcNumber
) {

  // NEVER disable admin.
  if (
    String(tfcNumber) ===
    ADMIN_TFC_NUMBER
  ) {
    alert(
      'The main configuration account cannot be disabled.'
    );
    return;
  }


  if (
    String(tfcNumber).startsWith('A')
  ) {
    return;
  }


  const profile =
    allProfiles.find(
      (item) =>
        String(item.tfcNumber) ===
        String(tfcNumber)
    );


  if (!profile) {
    alert(
      'Profile could not be found.'
    );
    return;
  }


  const confirmed =
    confirm(
      `Disable account for ${profile.name || 'this operator'}?\n\n` +
      `TFC Number: ${tfcNumber}\n\n` +
      `The TFC number will become A${tfcNumber}.`
    );


  if (!confirmed) {
    return;
  }


  try {

    $('.window-toolbar .toolbar-status')
      .textContent =
      'PROFILE_ARRAY // DISABLING…';


    await updateAccountNumber(
      tfcNumber,
      `A${tfcNumber}`
    );


    // Reload database.
    allProfiles =
      await fetchProfiles();

    renderProfiles(
      allProfiles
    );


    $('.window-toolbar .toolbar-status')
      .textContent =
      'PROFILE_ARRAY // SYNCED';


    $('.editor-status').innerHTML =
      `<span>● ${allProfiles.length} profiles loaded</span>` +
      '<span>Registry synchronized</span>' +
      '<span>Account disabled</span>';

  } catch (error) {

    console.error(error);

    $('.window-toolbar .toolbar-status')
      .textContent =
      'PROFILE_ARRAY // ERROR';

    alert(
      error.message ||
      'Unable to disable the account.'
    );
  }
}


// ------------------------------------------------------------
// ENABLE ACCOUNT
// ------------------------------------------------------------

async function enableAccount(
  tfcNumber
) {

  // Safety check.
  if (
    String(tfcNumber) ===
    ADMIN_TFC_NUMBER
  ) {
    return;
  }


  const disabledNumber =
    String(tfcNumber);


  if (
    !disabledNumber.startsWith('A')
  ) {
    return;
  }


  // Remove the leading A.
  const originalNumber =
    disabledNumber.substring(1);


  const profile =
    allProfiles.find(
      (item) =>
        String(item.tfcNumber) ===
        disabledNumber
    );


  if (!profile) {
    alert(
      'Disabled profile could not be found.'
    );
    return;
  }


  const confirmed =
    confirm(
      `Enable account for ${profile.name || 'this operator'}?\n\n` +
      `Current TFC Number: ${disabledNumber}\n\n` +
      `It will be restored to ${originalNumber}.`
    );


  if (!confirmed) {
    return;
  }


  try {

    $('.window-toolbar .toolbar-status')
      .textContent =
      'PROFILE_ARRAY // ENABLING…';


    await updateAccountNumber(
      disabledNumber,
      originalNumber
    );


    // Reload database.
    allProfiles =
      await fetchProfiles();

    renderProfiles(
      allProfiles
    );


    $('.window-toolbar .toolbar-status')
      .textContent =
      'PROFILE_ARRAY // SYNCED';


    $('.editor-status').innerHTML =
      `<span>● ${allProfiles.length} profiles loaded</span>` +
      '<span>Registry synchronized</span>' +
      '<span>Account enabled</span>';

  } catch (error) {

    console.error(error);

    $('.window-toolbar .toolbar-status')
      .textContent =
      'PROFILE_ARRAY // ERROR';

    alert(
      error.message ||
      'Unable to enable the account.'
    );
  }
}


