// ------------------------------------------------------------
// REFRESH PROFILE LIST
// ------------------------------------------------------------

const refreshButton =
  $('#refreshProfilesButton');

const refreshOverlay =
  $('#refreshOverlay');

const refreshProgress =
  $('#refreshProgress');

const refreshPercent =
  $('#refreshPercent');

const refreshMessage =
  $('#refreshMessage');


function waitForRefresh(milliseconds = 0) {
  return new Promise((resolve) => setTimeout(resolve, milliseconds));
}

async function filterProfilesWithoutBlocking(profiles) {
  const selectedClasses = Array.from(
    document.querySelectorAll('.class-filter:checked')
  ).map((input) => input.value.toLowerCase());

  const selectedMountains = Array.from(
    document.querySelectorAll('.mountain-filter:checked')
  ).map((input) => input.value.toLowerCase());

  const filtered = [];

  for (let index = 0; index < profiles.length; index++) {
    const profile = profiles[index];
    const profileClasses = (profile.classes || [])
      .map((item) => String(item).toLowerCase());
    const profileMountains = (profile.mountains || [])
      .map((item) => String(item).toLowerCase());

    const classMatches =
      selectedClasses.length === 0 ||
      selectedClasses.some((selected) => profileClasses.includes(selected));

    const mountainMatches =
      selectedMountains.length === 0 ||
      selectedMountains.some((selected) => profileMountains.includes(selected));

    if (classMatches && mountainMatches) {
      filtered.push(profile);
    }

    // Keep each synchronous section well below the preview watchdog limit.
    if (index % 10 === 0) {
      await waitForRefresh(0);
    }
  }

  return filtered;
}

async function refreshProfileList() {

  if (!refreshButton || refreshInProgress) {
    return;
  }

  refreshInProgress = true;
  refreshButton.disabled = true;

  // ----------------------------------------------------------
  // SAVE CURRENT FILTER32 OPTIONS BEFORE REFRESH
  // ----------------------------------------------------------

  if (typeof saveFilter32Options === 'function') {
    saveFilter32Options();
  }


  // Show refresh window.
  refreshOverlay.classList.remove('hidden');

  refreshProgress.style.width = '0%';
  refreshPercent.textContent = '0%';

  refreshMessage.textContent =
    'Contacting profile registry...';


  // ----------------------------------------------------------
  // WINDOWS-STYLE PROGRESS ANIMATION
  // ----------------------------------------------------------

  try {

    // Keep the progress sequence explicit so every stage gets its own
    // browser task instead of being handled by one long loop.
    refreshProgress.style.width = '15%';
    refreshPercent.textContent = '15%';
    refreshMessage.textContent = 'Opening registry connection...';
    await waitForRefresh(220);

    refreshProgress.style.width = '32%';
    refreshPercent.textContent = '32%';
    refreshMessage.textContent = 'Requesting profile array...';
    await waitForRefresh(220);

    refreshProgress.style.width = '51%';
    refreshPercent.textContent = '51%';
    refreshMessage.textContent = 'Downloading profile data...';
    await waitForRefresh(220);

    refreshMessage.textContent = 'Downloading profile data...';
    await waitForRefresh(0);

    const freshProfiles = await fetchProfiles();
    allProfiles = freshProfiles;

    refreshProgress.style.width = '68%';
    refreshPercent.textContent = '68%';
    refreshMessage.textContent = 'Decrypting profiles in memory...';
    await waitForRefresh(0);

    restoreFilter32Options();
    await waitForRefresh(0);

    refreshProgress.style.width = '82%';
    refreshPercent.textContent = '82%';
    refreshMessage.textContent = 'Synchronizing profile list...';
    await waitForRefresh(0);

    const filteredProfiles =
      await filterProfilesWithoutBlocking(allProfiles);

    await renderProfiles(filteredProfiles);

    const filterResultCount = $('#filterResultCount');
    if (filterResultCount) {
      filterResultCount.textContent =
        `${filteredProfiles.length} of ${allProfiles.length} profiles`;
    }


    // --------------------------------------------------------
    // FINISH PROGRESS
    // --------------------------------------------------------

    refreshMessage.textContent =
      'Profile registry synchronized.';

    refreshProgress.style.width =
      '100%';

    refreshPercent.textContent =
      '100%';


    $('.window-toolbar .toolbar-status')
      .textContent =
      'PROFILE_ARRAY // READY';


    await new Promise(
      (resolve) =>
        setTimeout(resolve, 500)
    );


    // Close dialog.
    refreshOverlay.classList.add(
      'hidden'
    );


  } catch (error) {

    console.error(
      'Profile refresh failed:',
      error
    );


    refreshProgress.style.width =
      '100%';

    refreshPercent.textContent =
      'ERR';

    refreshMessage.textContent =
      'Unable to refresh profile registry.';


    $('.window-toolbar .toolbar-status')
      .textContent =
      'PROFILE_ARRAY // ERROR';


    await new Promise(
      (resolve) =>
        setTimeout(resolve, 1200)
    );


    refreshOverlay.classList.add(
      'hidden'
    );

  } finally {

    refreshInProgress = false;
    refreshButton.disabled = false;

  }
}

