const filterOverlay =
  $('#filterOverlay');

const FILTER32_STORAGE_KEY =
  '550c_filter32_options';


// ------------------------------------------------------------
// GET CURRENT FILTER STATE
// ------------------------------------------------------------

function getFilter32Options() {

  return {
    classes: Array.from(
      document.querySelectorAll(
        '.class-filter:checked'
      )
    ).map(
      (input) => input.value
    ),

    mountains: Array.from(
      document.querySelectorAll(
        '.mountain-filter:checked'
      )
    ).map(
      (input) => input.value
    )
  };
}


// ------------------------------------------------------------
// SAVE FILTER STATE
// ------------------------------------------------------------

function saveFilter32Options() {

  const options =
    getFilter32Options();

  localStorage.setItem(
    FILTER32_STORAGE_KEY,
    JSON.stringify(options)
  );

  console.log(
    'FILTER32 options saved:',
    options
  );
}


// ------------------------------------------------------------
// RESTORE FILTER STATE
// ------------------------------------------------------------

function restoreFilter32Options() {

  const saved =
    localStorage.getItem(
      FILTER32_STORAGE_KEY
    );

  if (!saved) {
    return;
  }

  try {

    const options =
      JSON.parse(saved);


    // Clear current selections first.
    document
      .querySelectorAll(
        '.class-filter, .mountain-filter'
      )
      .forEach(
        (input) => {
          input.checked = false;
        }
      );


    // Restore classes.
    if (Array.isArray(options.classes)) {

      document
        .querySelectorAll(
          '.class-filter'
        )
        .forEach(
          (input) => {

            input.checked =
              options.classes.includes(
                input.value
              );

          }
        );
    }


    // Restore mountains.
    if (Array.isArray(options.mountains)) {

      document
        .querySelectorAll(
          '.mountain-filter'
        )
        .forEach(
          (input) => {

            input.checked =
              options.mountains.includes(
                input.value
              );

          }
        );
    }


    updateFilterResultCount();

    console.log(
      'FILTER32 options restored:',
      options
    );

  } catch (error) {

    console.error(
      'FILTER32 restore failed:',
      error
    );

  }
}


// ------------------------------------------------------------
// UPDATE RESULT COUNT
// ------------------------------------------------------------

function updateFilterResultCount() {

  const selectedClasses =
    Array.from(
      document.querySelectorAll(
        '.class-filter:checked'
      )
    ).map(
      (input) =>
        input.value.toLowerCase()
    );


  const selectedMountains =
    Array.from(
      document.querySelectorAll(
        '.mountain-filter:checked'
      )
    ).map(
      (input) =>
        input.value.toLowerCase()
    );


  const filtered =
    allProfiles.filter(
      (profile) => {

        const profileClasses =
          (profile.classes || [])
            .map(
              (item) =>
                String(item).toLowerCase()
            );


        const profileMountains =
          (profile.mountains || [])
            .map(
              (item) =>
                String(item).toLowerCase()
            );


        const classMatches =
          selectedClasses.length === 0 ||
          selectedClasses.some(
            (selected) =>
              profileClasses.includes(
                selected
              )
          );


        const mountainMatches =
          selectedMountains.length === 0 ||
          selectedMountains.some(
            (selected) =>
              profileMountains.includes(
                selected
              )
          );


        return (
          classMatches &&
          mountainMatches
        );
      }
    );


  const result =
    $('#filterResultCount');

  if (result) {

    result.textContent =
      `${filtered.length} of ${allProfiles.length} profiles`;

  }
}


