// GLOBAL WINDOW DRAGGING
// ==========================================================

let windowZIndex = 1000;

function makeWindowDraggable(windowElement, titleBar) {
  if (!windowElement || !titleBar) return;

  let dragging = false;
  let offsetX = 0;
  let offsetY = 0;

  titleBar.addEventListener("mousedown", (event) => {

    // Never start dragging from controls/buttons
    if (
      event.target.closest("button") ||
      event.target.closest("input") ||
      event.target.closest("select") ||
      event.target.closest("textarea") ||
      event.target.closest("a")
    ) {
      return;
    }

    // Don't drag maximized KAMAR
    if (
      windowElement.classList.contains("kamar-maximized")
    ) {
      return;
    }

    dragging = true;

    const rect =
      windowElement.getBoundingClientRect();

    offsetX =
      event.clientX - rect.left;

    offsetY =
      event.clientY - rect.top;

    // Convert current visual position
    // into fixed coordinates.
    windowElement.style.position = "fixed";
    windowElement.style.left =
      rect.left + "px";
    windowElement.style.top =
      rect.top + "px";

    windowElement.style.margin = "0";

    // Bring to front.
    windowZIndex++;

    windowElement.style.zIndex =
      windowZIndex;

    event.preventDefault();
  });


  document.addEventListener("mousemove", (event) => {

    if (!dragging) return;

    let x =
      event.clientX - offsetX;

    let y =
      event.clientY - offsetY;


    // Keep title bar accessible.
    const minX =
      -windowElement.offsetWidth + 80;

    const maxX =
      window.innerWidth - 80;

    const minY = 0;

    const maxY =
      window.innerHeight - 30;


    x =
      Math.max(
        minX,
        Math.min(x, maxX)
      );

    y =
      Math.max(
        minY,
        Math.min(y, maxY)
      );


    windowElement.style.left =
      x + "px";

    windowElement.style.top =
      y + "px";
  });


  document.addEventListener("mouseup", () => {
    dragging = false;
  });
}


// ==========================================================
// ENABLE DRAGGING ON ALL WINDOWS
// ==========================================================

function enableAllWindowDragging() {

  const windows =
    document.querySelectorAll(
      [
        ".window",
        ".window-shell",
        ".utility-window",
        ".kamar-window",
        ".iframe-diagnostics-window"
      ].join(", ")
    );


  windows.forEach((windowElement) => {

    const titleBar =
      windowElement.querySelector(
        [
          ".titlebar",
          ".window-titlebar",
          ".utility-titlebar",
          ".kamar-titlebar",
          ".iframe-diagnostics-titlebar"
        ].join(", ")
      );


    if (!titleBar) {
      console.warn(
        "No title bar found for window:",
        windowElement
      );

      return;
    }


    // Prevent installing the handler twice.
    if (
      windowElement.dataset.dragEnabled === "true"
    ) {
      return;
    }


    windowElement.dataset.dragEnabled =
      "true";


    makeWindowDraggable(
      windowElement,
      titleBar
    );
  });
}


// Enable after the DOM is loaded.
enableAllWindowDragging();
