function showIframeDiagnostics() {

  console.log(
    '[iframe.drv.exe] Opening diagnostics...'
  );


  if (!iframeDiagnosticsWindow) {

    console.error(
      '[iframe.drv.exe] Diagnostics window not found.'
    );

    return;
  }


  // ----------------------------------------------------------
  // DRIVER NOT LOADED
  // ----------------------------------------------------------

  if (!window.IFrameMgrDriver) {

    console.error(
      '[iframe.drv.exe] iframemgr.drv is not loaded.'
    );


    if (iframeDiagnosticsContent) {

      iframeDiagnosticsContent.innerHTML = `
        <div class="diagnostic-row">
          <span>Driver</span>
          <span>NOT LOADED</span>
        </div>

        <div class="diagnostic-row">
          <span>Connection</span>
          <span>UNAVAILABLE</span>
        </div>
      `;
    }


    if (iframeDiagnosticsStatus) {

      iframeDiagnosticsStatus.textContent =
        'Driver status: NOT LOADED';
    }


    iframeDiagnosticsWindow.style.display =
      'block';

    return;
  }


  // ----------------------------------------------------------
  // GET DRIVER INFORMATION
  // ----------------------------------------------------------

  const diagnostics =
    window.IFrameMgrDriver.getDiagnostics();


  console.log(
    '[iframe.drv.exe] Diagnostics:',
    diagnostics
  );


  // ----------------------------------------------------------
  // RENDER DIAGNOSTICS
  // ----------------------------------------------------------

  if (iframeDiagnosticsContent) {

    iframeDiagnosticsContent.innerHTML = `

      <div class="diagnostic-row">
        <span>Driver</span>
        <span>${diagnostics.driver || '—'}</span>
      </div>

      <div class="diagnostic-row">
        <span>Version</span>
        <span>${diagnostics.version || '—'}</span>
      </div>

      <div class="diagnostic-row">
        <span>Status</span>
        <span>${diagnostics.status || '—'}</span>
      </div>

      <div class="diagnostic-row">
        <span>Connected</span>
        <span>
          ${diagnostics.connected ? 'YES' : 'NO'}
        </span>
      </div>

      <div class="diagnostic-row">
        <span>Iframe Loaded</span>
        <span>
          ${diagnostics.iframeLoaded ? 'YES' : 'NO'}
        </span>
      </div>

      <div class="diagnostic-row">
        <span>Iframe URL</span>
        <span>
          ${diagnostics.iframeURL || '—'}
        </span>
      </div>

      <div class="diagnostic-row">
        <span>Iframe Origin</span>
        <span>
          ${diagnostics.iframeOrigin || '—'}
        </span>
      </div>

      <div class="diagnostic-row">
        <span>Messages Sent</span>
        <span>
          ${diagnostics.messagesSent ?? 0}
        </span>
      </div>

      <div class="diagnostic-row">
        <span>Messages Received</span>
        <span>
          ${diagnostics.messagesReceived ?? 0}
        </span>
      </div>

      <div class="diagnostic-row">
        <span>Last Message</span>
        <span>
          ${diagnostics.lastMessage || 'NONE'}
        </span>
      </div>

      <div class="diagnostic-row">
        <span>Last Message Time</span>
        <span>
          ${diagnostics.lastMessageTime || '—'}
        </span>
      </div>

    `;
  }


  if (iframeDiagnosticsStatus) {

    iframeDiagnosticsStatus.textContent =
      `Driver status: ${
        diagnostics.status || 'UNKNOWN'
      }`;
  }


  // ----------------------------------------------------------
  // SHOW WINDOW
  // ----------------------------------------------------------

  iframeDiagnosticsWindow.style.display =
    'block';


  // Bring diagnostics window to front.
  windowZIndex++;

  iframeDiagnosticsWindow.style.zIndex =
    windowZIndex;
}


