/* ==========================================================
   LOAD FILESYSTEM
   ========================================================== */

async function loadFileSystem() {

    if (!fileSystemAuthenticated) {
        return;
    }

    try {

        fileSystemStatus.textContent =
            'FILE_SYSTEM // QUERYING';

        const rows =
            await fileSystemRequest(
                `/rest/v1/${FILESYSTEM_TABLE}?select=id,file_array`
            );

        if (!Array.isArray(rows)) {
            throw new Error('Invalid filesystem response.');
        }


        /*
         * The requested schema only contains:
         *
         * file_system
         * └── file_array
         *
         * Therefore the first row is used as the
         * filesystem root.
         */

        if (rows.length === 0) {

            const created =
                await fileSystemRequest(
                    `/rest/v1/${FILESYSTEM_TABLE}`,
                    {
                        method: 'POST',

                        headers: {
                            Prefer:
                                'return=representation'
                        },

                        body: JSON.stringify({
                            file_array: {}
                        })
                    }
                );

            if (
                !Array.isArray(created) ||
                !created[0]
            ) {
                throw new Error(
                    'Unable to create filesystem.'
                );
            }

            fileSystemRowId =
                created[0].id;

            fileSystemData = {};

        } else {

            fileSystemRowId =
                rows[0].id;

            fileSystemData =
                normalizeFileSystem(
                    rows[0].file_array
                );
        }

        fileSystemCurrentPath = [];

        fileSystemSelectedPath = null;

        fileSystemExpandedPaths.clear();

        renderFileSystem();

        fileSystemStatus.textContent =
            'FILE_SYSTEM // ONLINE';

        fileSystemStorageStatus.textContent =
            'SUPABASE // file_system.file_array';

    } catch (error) {

        console.error(
            'KAMAR FileSystem:',
            error
        );

        fileSystemStatus.textContent =
            'FILE_SYSTEM // ERROR';

        fileSystemStorageStatus.textContent =
            error.message;
    }
}


/* ==========================================================
   NORMALIZE FILESYSTEM
   ========================================================== */

function normalizeFileSystem(value) {

    // Some Supabase schemas return JSON columns as text. Parse that
    // representation before rendering or modifying the filesystem.
    if (typeof value === 'string') {
        try {
            value = JSON.parse(value);
        } catch {
            return {};
        }
    }

    if (
        !value ||
        typeof value !== 'object' ||
        Array.isArray(value)
    ) {
        return {};
    }

    return value;
}


/* ==========================================================
   SAVE FILESYSTEM
   ========================================================== */

async function saveFileSystem() {

    if (!fileSystemAuthenticated) {
        return;
    }

    if (!fileSystemRowId) {
        return;
    }

    try {

        fileSystemStatus.textContent =
            'FILE_SYSTEM // SAVING';

        /*
         * JSON.stringify safely escapes:
         *
         * "
         * \
         * newline
         * tab
         * etc.
         *
         * Do NOT manually add backslashes to
         * quotation marks here.
         */

        const serialized =
            JSON.stringify(
                fileSystemData
            );

        /*
         * Parse it again so the REST API receives
         * actual JSON rather than a double-encoded
         * JSON string.
         */

        const safeJson =
            JSON.parse(serialized);

        const savedRows =
            await fileSystemRequest(
                `/rest/v1/${FILESYSTEM_TABLE}?id=eq.${encodeURIComponent(fileSystemRowId)}`,
                {
                    method: 'PATCH',

                    headers: {
                        Prefer: 'return=representation'
                    },

                    body: JSON.stringify({
                        file_array: safeJson
                    })
                }
            );

        // PostgREST can return a successful response even when no row
        // matched the filter. Treat that as a failed save instead of
        // reporting success while the data remains only in memory.
        if (!Array.isArray(savedRows) || savedRows.length === 0) {
            throw new Error(
                'Filesystem save matched no database row.'
            );
        }

        fileSystemStatus.textContent =
            'FILE_SYSTEM // SAVED';

        fileSystemEditorStatus.textContent =
            'FILE SYSTEM SAVED';

    } catch (error) {

        console.error(error);

        fileSystemStatus.textContent =
            'FILE_SYSTEM // SAVE ERROR';

        fileSystemEditorStatus.textContent =
            error.message;
    }
}


/* ==========================================================
   GET DIRECTORY
   ========================================================== */

function getDirectory(path) {

    let current =
        fileSystemData;

    for (const part of path) {

        if (
            !current ||
            typeof current !== 'object'
        ) {
            return null;
        }

        const item =
            current[part];

        if (
            !item ||
            item.__type !== 'folder'
        ) {
            return null;
        }

        current =
            item.children || {};
    }

    return current;
}


/* ==========================================================
   GET ITEM
   ========================================================== */

function getFileSystemItem(path) {

    if (!path.length) {
        return fileSystemData;
    }

    let current =
        fileSystemData;

    for (let i = 0; i < path.length; i++) {

        if (
            !current ||
            typeof current !== 'object'
        ) {
            return null;
        }

        const name =
            path[i];

        if (!(name in current)) {
            return null;
        }

        const item =
            current[name];

        if (
            i < path.length - 1
        ) {

            if (
                !item ||
                item.__type !== 'folder'
            ) {
                return null;
            }

            current =
                item.children || {};
        } else {

            return item;
        }
    }

    return null;
}


/* ==========================================================
   RENDER FILESYSTEM
   ========================================================== */

function renderFileSystem() {

    fileSystemTree.innerHTML = '';

    const rootRow =
        createTreeRow(
            'KAMAR FileSystem',
            [],
            'folder',
            true,
            0
        );

    fileSystemTree.appendChild(
        rootRow
    );

    renderDirectory(
        fileSystemData,
        [],
        1,
        fileSystemTree
    );

    updateFileSystemPath();

    updateItemCount();
}


/* ==========================================================
   RENDER DIRECTORY
   ========================================================== */

function renderDirectory(
    directory,
    parentPath,
    depth,
    container
) {

    if (
        !directory ||
        typeof directory !== 'object'
    ) {
        return;
    }

    const entries =
        Object.entries(directory);

    entries.sort(
        ([nameA, itemA], [nameB, itemB]) => {

            const folderA =
                isFolder(itemA);

            const folderB =
                isFolder(itemB);

            if (folderA !== folderB) {
                return folderA ? -1 : 1;
            }

            return nameA.localeCompare(
                nameB,
                undefined,
                {
                    numeric: true,
                    sensitivity: 'base'
                }
            );
        }
    );


    for (const [name, item] of entries) {

        const path =
            [...parentPath, name];

        const folder =
            isFolder(item);

        const expanded =
            folder &&
            fileSystemExpandedPaths.has(
                pathKey(path)
            );

        const row =
            createTreeRow(
                name,
                path,
                folder ? 'folder' : 'file',
                expanded,
                depth
            );

        container.appendChild(row);

        if (
            folder &&
            expanded
        ) {

            renderDirectory(
                item.children || {},
                path,
                depth + 1,
                container
            );
        }
    }
}


/* ==========================================================
   TREE ROW
   ========================================================== */

function createTreeRow(
    name,
    path,
    type,
    expanded,
    depth
) {

    const row =
        document.createElement('div');

    row.className =
        'filesystem-tree-row';

    if (
        fileSystemSelectedPath &&
        pathsEqual(
            path,
            fileSystemSelectedPath
        )
    ) {
        row.classList.add('selected');
    }

    row.style.paddingLeft =
        `${5 + depth * 16}px`;


    const arrow =
        document.createElement('span');

    arrow.className =
        'filesystem-tree-arrow';

    if (type === 'folder') {

        arrow.textContent =
            expanded ? '▼' : '▶';

    } else {

        arrow.textContent =
            '';
    }


    const icon =
        document.createElement('span');

    icon.className =
        'filesystem-tree-icon';

    if (type === 'folder') {
        icon.textContent = '📁';
    } else {
        const iconUrl = getFileIconUrl(name);

        if (iconUrl) {
            const image = document.createElement('img');
            image.src = iconUrl;
            image.alt = '';
            image.className = 'filesystem-file-icon';
            icon.appendChild(image);
        } else {
            icon.textContent = '📄';
        }
    }


    const label =
        document.createElement('span');

    label.className =
        'filesystem-tree-name';

    label.textContent =
        name;


    row.appendChild(arrow);
    row.appendChild(icon);
    row.appendChild(label);


    row.addEventListener(
        'click',
        () => {

            if (type === 'folder') {

                const key =
                    pathKey(path);

                if (
                    fileSystemExpandedPaths.has(
                        key
                    )
                ) {

                    fileSystemExpandedPaths.delete(
                        key
                    );

                } else {

                    fileSystemExpandedPaths.add(
                        key
                    );
                }

                fileSystemCurrentPath =
                    [...path];

                // Keep the folder selected so it can be deleted.
                fileSystemSelectedPath =
                    [...path];

                clearEditor(true);

                fileSystemSelectedName.textContent =
                    path.length
                        ? path[path.length - 1]
                        : 'KAMAR FileSystem';

                fileSystemSelectedType.textContent =
                    'FOLDER';

                renderFileSystem();

            } else {

                selectFile(path);
            }
        }
    );


    row.addEventListener(
        'dblclick',
        () => {

            if (type === 'file') {
                selectFile(path);
            }
        }
    );


    return row;
}


/* ==========================================================
   SELECT FILE
   ========================================================== */

function selectFile(path) {

    const item =
        getFileSystemItem(path);

    if (
        typeof item !== 'string'
    ) {
        return;
    }

    fileSystemSelectedPath =
        [...path];

    fileSystemCurrentPath =
        path.slice(0, -1);

    fileSystemEditor.disabled =
        false;

    fileSystemEditor.value =
        item;

    fileSystemSelectedName.textContent =
        path[path.length - 1];

    fileSystemSelectedType.textContent =
        getExtension(
            path[path.length - 1]
        ) || 'FILE';

    fileSystemEditorStatus.textContent =
        'FILE OPEN';

    renderFileSystem();
    openCodeFileAfterSelection(path[path.length - 1]);
}


/* ==========================================================
   CLEAR EDITOR
   ========================================================== */

function clearEditor(preserveSelection = false) {

    if (!preserveSelection) {
        fileSystemSelectedPath = null;
    }

    fileSystemEditor.value = '';

    fileSystemEditor.disabled = true;

    fileSystemSelectedName.textContent =
        'No file selected';

    fileSystemSelectedType.textContent =
        '—';

    fileSystemEditorStatus.textContent =
        'READY';
}


/* ==========================================================
   SAVE CURRENT FILE
   ========================================================== */

async function saveCurrentFile() {

    if (
        !fileSystemSelectedPath
    ) {
        fileSystemEditorStatus.textContent =
            'NO FILE SELECTED';

        return;
    }

    const item =
        getFileSystemItem(
            fileSystemSelectedPath
        );

    if (
        typeof item !== 'string'
    ) {
        return;
    }

    const parentPath =
        fileSystemSelectedPath.slice(
            0,
            -1
        );

    const filename =
        fileSystemSelectedPath[
            fileSystemSelectedPath.length - 1
        ];

    const directory =
        getDirectory(parentPath);

    if (!directory) {
        return;
    }

    /*
     * Store the raw text.
     *
     * JSON.stringify() handles quotes,
     * backslashes, newlines, etc. when the
     * complete filesystem is sent to Supabase.
     */

    directory[filename] =
        fileSystemEditor.value;

    await saveFileSystem();

    // Keep the editor state aligned with the object that was persisted.
    fileSystemEditor.value = directory[filename];

    renderFileSystem();

    fileSystemEditorStatus.textContent =
        'FILE SAVED';
}


/* ==========================================================
   CREATE FILE
   ========================================================== */

async function createFile() {

    const filenameInput =
        prompt(
            'Enter filename (without extension):'
        );

    if (
        filenameInput === null
    ) {
        return;
    }

    const filename =
        filenameInput.trim();


    if (!filename) {

        alert(
            'Filename cannot be empty.'
        );

        return;
    }


    const extensionInput =
        prompt(
            'Enter file extension (example: .txt, .exe, .json):'
        );

    if (
        extensionInput === null
    ) {
        return;
    }

    let extension =
        extensionInput.trim();


    /*
     * All extensions are supported.
     *
     * If the user types:
     *
     * txt
     *
     * it becomes:
     *
     * .txt
     *
     * If they type:
     *
     * .custom
     *
     * it stays:
     *
     * .custom
     */

    if (
        extension &&
        !extension.startsWith('.')
    ) {
        extension =
            `.${extension}`;
    }


    const fullName =
        filename + extension;


    if (
        /[\/\\]/.test(fullName)
    ) {

        alert(
            'Filename cannot contain / or \\.'
        );

        return;
    }


    const directory =
        getDirectory(
            fileSystemCurrentPath
        );

    if (!directory) {
        return;
    }


    if (
        Object.prototype.hasOwnProperty.call(
            directory,
            fullName
        )
    ) {

        alert(
            'A file or folder with that name already exists.'
        );

        return;
    }


    directory[fullName] =
        '';

    fileSystemExpandedPaths.add(
        pathKey(fileSystemCurrentPath)
    );

    await saveFileSystem();

    renderFileSystem();

    selectFile([
        ...fileSystemCurrentPath,
        fullName
    ]);
}


/* ==========================================================
   CREATE FOLDER
   ========================================================== */

async function createFolder() {

    const nameInput =
        prompt(
            'Enter folder name:'
        );

    if (
        nameInput === null
    ) {
        return;
    }

    const name =
        nameInput.trim();


    if (!name) {

        alert(
            'Folder name cannot be empty.'
        );

        return;
    }


    if (
        /[\/\\]/.test(name)
    ) {

        alert(
            'Folder name cannot contain / or \\.'
        );

        return;
    }


    const directory =
        getDirectory(
            fileSystemCurrentPath
        );

    if (!directory) {
        return;
    }


    if (
        Object.prototype.hasOwnProperty.call(
            directory,
            name
        )
    ) {

        alert(
            'A file or folder with that name already exists.'
        );

        return;
    }


    directory[name] = {

        __type: 'folder',

        children: {}

    };


    fileSystemExpandedPaths.add(
        pathKey(fileSystemCurrentPath)
    );


    await saveFileSystem();

    renderFileSystem();
}


/* ==========================================================
   DELETE ITEM
   ========================================================== */

async function deleteSelectedFileSystemItem() {

    if (
        !fileSystemSelectedPath ||
        fileSystemSelectedPath.length === 0
    ) {

        alert(
            'Select a file or folder first.'
        );

        return;
    }

    const selectedItem =
        getFileSystemItem(fileSystemSelectedPath);

    if (selectedItem === null) {
        alert('The selected file or folder no longer exists.');
        return;
    }


    const name =
        fileSystemSelectedPath[
            fileSystemSelectedPath.length - 1
        ];

    const item =
        getFileSystemItem(
            fileSystemSelectedPath
        );

    const type =
        isFolder(item)
            ? 'folder'
            : 'file';


    const confirmed =
        confirm(
            `Delete ${type} "${name}"?`
        );

    if (!confirmed) {
        return;
    }


    const parentPath =
        fileSystemSelectedPath.slice(
            0,
            -1
        );

    const directory =
        getDirectory(parentPath);

    if (!directory) {
        return;
    }


    delete directory[name];


    fileSystemSelectedPath =
        null;

    fileSystemEditor.value =
        '';

    fileSystemEditor.disabled =
        true;


    await saveFileSystem();

    renderFileSystem();

    fileSystemEditorStatus.textContent =
        'ITEM DELETED';
}


/* ==========================================================
   DOWNLOAD FILE
   ========================================================== */

function downloadSelectedFile() {

    if (!fileSystemSelectedPath) {
        alert('Select a file first.');
        return;
    }

    const item = getFileSystemItem(fileSystemSelectedPath);

    if (typeof item !== 'string') {
        alert('Only files can be downloaded.');
        return;
    }

    const filename =
        fileSystemSelectedPath[fileSystemSelectedPath.length - 1];

    // Use the editor value so a recently edited file downloads exactly
    // as displayed, even if the user has not saved it to Supabase yet.
    const contents =
        fileSystemEditor && !fileSystemEditor.disabled
            ? fileSystemEditor.value
            : item;

    const blob = new Blob([contents], {
        type: 'application/octet-stream'
    });

    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');

    link.href = url;
    link.download = filename;
    link.style.display = 'none';
    document.body.appendChild(link);

    try {
        link.click();
        fileSystemEditorStatus.textContent = 'FILE DOWNLOADED';
    } catch (error) {
        console.error('File download failed:', error);
        fileSystemEditorStatus.textContent = 'DOWNLOAD ERROR';
        alert('Unable to download the selected file.');
    } finally {
        link.remove();
        setTimeout(() => URL.revokeObjectURL(url), 1000);
    }
}


/* ==========================================================
   PATH
   ========================================================== */

function updateFileSystemPath() {

    const path =
        fileSystemCurrentPath.length
            ? '/' +
              fileSystemCurrentPath.join('/')
            : '/';

    fileSystemPath.textContent =
        path;
}


/* ==========================================================
   ITEM COUNT
   ========================================================== */

function updateItemCount() {

    let count = 0;

    function walk(directory) {

        for (
            const item of Object.values(directory)
        ) {

            count++;

            if (isFolder(item)) {

                walk(
                    item.children || {}
                );
            }
        }
    }

    walk(fileSystemData);

    fileSystemItemCount.textContent =
        `${count} ITEM${count === 1 ? '' : 'S'}`;
}


/* ==========================================================
   HELPERS
   ========================================================== */

function isFolder(item) {

    return !!(
        item &&
        typeof item === 'object' &&
        item.__type === 'folder'
    );
}


function pathKey(path) {

    return JSON.stringify(path);
}


function pathsEqual(a, b) {

    return (
        a.length === b.length &&
        a.every(
            (value, index) =>
                value === b[index]
        )
    );
}


function getExtension(filename) {

    const index =
        filename.lastIndexOf('.');

    if (
        index <= 0
    ) {
        return '';
    }

    return filename.slice(index);
}


/* ==========================================================
   UPLOAD32.EXE — CHUNKED FILE INTAKE
   ========================================================== */

function formatUploadSize(bytes) {
    if (!bytes) return '0 B';
    const units = ['B', 'KB', 'MB', 'GB', 'TB'];
    const index = Math.min(
        units.length - 1,
        Math.floor(Math.log(bytes) / Math.log(1024))
    );
    return `${(bytes / (1024 ** index)).toFixed(index ? 1 : 0)} ${units[index]}`;
}

function closeUpload32() {
    upload32Cancelled = true;
    upload32Overlay?.classList.add('hidden');
    if (uploadFileInput) uploadFileInput.value = '';
}

async function uploadFileToCurrentDirectory(file) {
    if (!file || !fileSystemAuthenticated) return;

    const directory = getDirectory(fileSystemCurrentPath);
    if (!directory) {
        alert('The selected upload folder is unavailable.');
        return;
    }

    if (Object.prototype.hasOwnProperty.call(directory, file.name)) {
        alert('A file with that name already exists.');
        return;
    }

    upload32Cancelled = false;
    upload32File.textContent = file.name;
    upload32Size.textContent = `0 B / ${formatUploadSize(file.size)}`;
    upload32Status.textContent = 'Reading file in chunks...';
    upload32Progress.style.width = '0%';
    upload32Percent.textContent = '0%';
    upload32Overlay.classList.remove('hidden');

    // Chunking keeps the UI responsive while handling large local files.
    const chunkSize = 1024 * 1024;
    const chunks = [];
    let uploadedBytes = 0;

    try {
        for (let offset = 0; offset < file.size; offset += chunkSize) {
            if (upload32Cancelled) return;

            const chunk = file.slice(offset, Math.min(offset + chunkSize, file.size));
            chunks.push(await chunk.arrayBuffer());
            uploadedBytes += chunk.size;

            const percent = file.size
                ? Math.round((uploadedBytes / file.size) * 100)
                : 100;

            upload32Progress.style.width = `${percent}%`;
            upload32Percent.textContent = `${percent}%`;
            upload32Size.textContent = `${formatUploadSize(uploadedBytes)} / ${formatUploadSize(file.size)}`;
            upload32Status.textContent = `Uploading chunk ${chunks.length}...`;

            await new Promise(resolve => setTimeout(resolve, 0));
        }

        if (upload32Cancelled) return;

        // JSON storage requires text; preserve binary bytes losslessly with base64.
        const bytes = new Uint8Array(file.size);
        let position = 0;
        for (const buffer of chunks) {
            bytes.set(new Uint8Array(buffer), position);
            position += buffer.byteLength;
        }

        let binary = '';
        const batchSize = 0x8000;
        for (let index = 0; index < bytes.length; index += batchSize) {
            binary += String.fromCharCode(...bytes.subarray(index, index + batchSize));
        }

        directory[file.name] = `data:${file.type || 'application/octet-stream'};base64,${btoa(binary)}`;
        await saveFileSystem();

        if (fileSystemStatus.textContent === 'FILE_SYSTEM // SAVE ERROR') return;

        fileSystemExpandedPaths.add(pathKey(fileSystemCurrentPath));
        fileSystemSelectedPath = [...fileSystemCurrentPath, file.name];
        renderFileSystem();
        selectFile(fileSystemSelectedPath);
        upload32Status.textContent = 'Upload complete and saved.';
        upload32Progress.style.width = '100%';
        upload32Percent.textContent = '100%';
        setTimeout(() => upload32Overlay.classList.add('hidden'), 700);
    } catch (error) {
        console.error('Upload32 failed:', error);
        upload32Status.textContent = `Upload failed: ${error.message}`;
    }
}

uploadFileButton?.addEventListener('click', () => uploadFileInput?.click());

uploadFileInput?.addEventListener('change', event => {
    const file = event.target.files?.[0];
    if (file) uploadFileToCurrentDirectory(file);
});

closeUpload32Button?.addEventListener('click', closeUpload32);
cancelUpload32Button?.addEventListener('click', closeUpload32);

